angular.module("huashanApp").directive("fileModel", [ "$parse", function($parse) {
    return {
        restrict: "A",
        link: function(scope, element, attrs) {
            var fileModel = $parse(attrs.fileModel);
            var fileModelSetterFn = fileModel.assign;
            element.bind("change", function() {
                scope.$apply(function() {
                    var elementSurroundingFileModelDiv = element[0];
                    var fileSelectedInElement = elementSurroundingFileModelDiv.files[0];
                    fileModelSetterFn(scope, fileSelectedInElement);
                });
            });
        }
    };
} ]);

angular.module("huashanApp").directive("fixedHeader", [ "$timeout", function($timeout) {
    return {
        restrict: "A",
        link: function($scope, $elem, $attrs, $ctrl) {
            $scope.$watch(function() {
                return $elem.find("tbody").is(":visible");
            }, function(newValue, oldValue) {
                if (newValue === true) {
                    $elem.find("thead, tbody").css("display", "");
                    $timeout(function() {
                        $elem.find("th").each(function(i, thElem) {
                            thElem = $(thElem);
                            tdElems = $elem.find("tbody tr:first td:nth-child(" + (i + 1) + ")");
                            var columnWidth = tdElems.width();
                            thElem.width(columnWidth);
                            tdElems.width(columnWidth);
                        });
                        $elem.find("thead").css({
                            display: "block"
                        });
                        $elem.find("tbody").css({
                            display: "block",
                            height: "520px",
                            overflow: "auto"
                        });
                        var scrollBarWidth = $elem.find("thead").width() - $elem.find("tbody")[0].clientWidth;
                        if (scrollBarWidth > 0) {
                            scrollBarWidth -= 2;
                            $elem.find("tbody tr:first td:last-child").each(function(i, elem) {
                                $(elem).width($(elem).width() - scrollBarWidth);
                            });
                        }
                    });
                }
            });
        }
    };
} ]);

angular.module("huashanApp").directive("scrollIf", function() {
    return function(scope, element, attrs) {
        scope.$watch(attrs.scrollIf, function(value) {
            if (value) {
                var pos = $(element).position().top + $(element).parent().parent().scrollTop();
                $(element).parent().parent().animate({
                    scrollTop: pos
                }, 300);
            }
        });
    };
});

var Common = function() {
    function Common() {}
    Common.prototype.makeActionIDfrom = function(display, menu) {
        var id = display.split(" ").join("");
        id = id.split("/").join("_");
        while (this.isActionIDduplicate(id, menu)) {
            id = id + "0";
        }
        return id;
    };
    Common.prototype.isActionIDduplicate = function(id, menu) {
        var answer = false;
        var displayIDArray = menu.map(function(item) {
            return item.ID;
        });
        if (displayIDArray.indexOf(id) !== -1) {
            answer = true;
        }
        return answer;
    };
    return Common;
}();

angular.module("huashanApp").directive("huashanVersion", [ "$modal", "mode", "Version", function($modal, mode, Version) {
    var templateUrl = "widget/version/app/template/version.html";
    if (mode === "standalone") {
        templateUrl = "template/version.html";
    }
    return {
        restrict: "A",
        templateUrl: templateUrl,
        link: function(scope) {
            scope.open = function(size) {
                var modalInstance = $modal.open({
                    templateUrl: "versionContent.html",
                    controller: "versionModalInstanceCtrl",
                    size: size,
                    resolve: {
                        versions: function() {
                            return Version.getVersion();
                        }
                    }
                });
            };
        }
    };
} ]);

